// Procedural sound: no downloads, everything is synthesized with WebAudio.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.windStarted = false;
    this.noiseBuffer = null;
    try {
      this.muted = localStorage.getItem('poeira_muted') === '1';
    } catch { /* ignore */ }
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    this.master.connect(this.ctx.destination);
    this.noiseBuffer = this.makeNoise(2.0);
  }

  makeNoise(seconds) {
    const ctx = this.ctx;
    const buffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * seconds), ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < data.length; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = white * 0.55 + last * 2.4;
    }
    return buffer;
  }

  setMuted(muted) {
    this.muted = muted;
    try { localStorage.setItem('poeira_muted', muted ? '1' : '0'); } catch { /* ignore */ }
    if (this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(muted ? 0 : 0.55, this.ctx.currentTime, 0.03);
    }
  }

  toggleMute() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  now() { return this.ctx ? this.ctx.currentTime : 0; }

  envGain(duration, peak = 1, attack = 0.005) {
    const ctx = this.ctx;
    const g = ctx.createGain();
    const t = ctx.currentTime;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0001, peak), t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    return g;
  }

  noiseBurst({ duration = 0.16, peak = 0.6, lowpass = 5200, highpass = 120, pan = 0, delay = 0 } = {}) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.playbackRate.value = 1;
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass';
    hp.frequency.value = highpass;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.setValueAtTime(lowpass, t);
    lp.frequency.exponentialRampToValueAtTime(Math.max(200, lowpass * 0.25), t + duration);
    const g = ctx.createGain();
    g.gain.setValueAtTime(peak, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    const p = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    if (p) p.pan.value = pan;
    src.connect(hp).connect(lp).connect(g);
    if (p) { g.connect(p).connect(this.master); } else g.connect(this.master);
    src.start(t);
    src.stop(t + duration + 0.02);
  }

  tone({ freq = 220, dur = 0.2, type = 'sine', peak = 0.3, slide = 0, delay = 0, pan = 0 } = {}) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide !== 0) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(peak, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const p = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    if (p) p.pan.value = pan;
    osc.connect(g);
    if (p) { g.connect(p).connect(this.master); } else g.connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.03);
  }

  shoot() {
    if (!this.ctx) return;
    this.noiseBurst({ duration: 0.22, peak: 0.85, lowpass: 7000, highpass: 300 });
    this.tone({ freq: 150, dur: 0.16, type: 'triangle', peak: 0.5, slide: -100 });
    this.tone({ freq: 62, dur: 0.3, type: 'sine', peak: 0.4, slide: -25 });
    this.noiseBurst({ duration: 0.4, peak: 0.09, lowpass: 1300, highpass: 80, delay: 0.02 });
  }

  enemyShoot() {
    this.noiseBurst({ duration: 0.16, peak: 0.32, lowpass: 4200, highpass: 250, pan: 0.2 });
    this.tone({ freq: 110, dur: 0.14, type: 'triangle', peak: 0.22, slide: -70 });
  }

  dryFire() {
    this.tone({ freq: 1500, dur: 0.035, type: 'square', peak: 0.09, slide: -900 });
    this.noiseBurst({ duration: 0.03, peak: 0.12, lowpass: 6000, highpass: 2500 });
  }

  hit() {
    this.tone({ freq: 210, dur: 0.1, type: 'triangle', peak: 0.25, slide: -130 });
    this.noiseBurst({ duration: 0.09, peak: 0.25, lowpass: 2200, highpass: 180 });
    this.tone({ freq: 880, dur: 0.18, type: 'sine', peak: 0.08, slide: 620, delay: 0.03 });
  }

  ricochet() {
    if (Math.random() > 0.55) return;
    this.tone({ freq: 1500 + Math.random() * 500, dur: 0.18, type: 'sine', peak: 0.07, slide: 1300 });
  }

  reload() {
    [0, 0.16, 0.42].forEach((d, i) => {
      this.tone({ freq: i === 2 ? 900 : 620, dur: 0.03, type: 'square', peak: 0.09, slide: -200, delay: d });
      this.noiseBurst({ duration: 0.03, peak: 0.09, lowpass: 7000, highpass: 2000, delay: d });
    });
  }

  reloadDone() {
    this.tone({ freq: 760, dur: 0.05, type: 'square', peak: 0.12, slide: 220 });
    this.tone({ freq: 1140, dur: 0.09, type: 'sine', peak: 0.07, delay: 0.03 });
  }

  hurt() {
    this.tone({ freq: 95, dur: 0.4, type: 'sawtooth', peak: 0.28, slide: -45 });
    this.noiseBurst({ duration: 0.28, peak: 0.4, lowpass: 900, highpass: 60 });
  }

  civil() {
    this.tone({ freq: 400, dur: 0.18, type: 'square', peak: 0.14, slide: -90 });
    this.tone({ freq: 300, dur: 0.24, type: 'square', peak: 0.12, slide: -60, delay: 0.1 });
  }

  deadeye() {
    this.tone({ freq: 420, dur: 1.1, type: 'sine', peak: 0.16, slide: -280 });
    this.tone({ freq: 210, dur: 1.3, type: 'triangle', peak: 0.11, slide: -120 });
    this.noiseBurst({ duration: 0.8, peak: 0.08, lowpass: 1200, highpass: 300 });
    this.tone({ freq: 1046, dur: 0.4, type: 'sine', peak: 0.05, delay: 0.1 });
  }

  deadeyeEnd() {
    this.tone({ freq: 250, dur: 0.5, type: 'sine', peak: 0.1, slide: 400 });
  }

  waveStart() {
    const notes = [392, 523, 659];
    notes.forEach((f, i) => {
      this.tone({ freq: f, dur: 0.3, type: 'triangle', peak: 0.11, delay: i * 0.13 });
      this.tone({ freq: f * 2, dur: 0.18, type: 'sine', peak: 0.035, delay: i * 0.13 });
    });
  }

  coin() {
    this.tone({ freq: 988, dur: 0.08, type: 'square', peak: 0.08 });
    this.tone({ freq: 1319, dur: 0.16, type: 'square', peak: 0.08, delay: 0.07 });
  }

  ui() {
    this.tone({ freq: 660, dur: 0.05, type: 'square', peak: 0.07, slide: 120 });
  }

  gameOver() {
    const notes = [392, 349, 311, 262];
    notes.forEach((f, i) => {
      this.tone({ freq: f, dur: 0.55, type: 'triangle', peak: 0.13, delay: i * 0.26 });
    });
    this.tone({ freq: 65, dur: 1.6, type: 'sine', peak: 0.12, delay: 0.4 });
  }

  startWind() {
    if (!this.ctx || this.windStarted) return;
    this.windStarted = true;
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 420;
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass';
    hp.frequency.value = 90;
    const g = ctx.createGain();
    g.gain.value = 0.035;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.09;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 0.018;
    lfo.connect(lfoGain).connect(g.gain);
    src.connect(hp).connect(lp).connect(g).connect(this.master);
    src.start();
    lfo.start();
  }
}

// Scenery: sky, desert, saloon and street props. Everything is pixel-aligned.

export const W = 320;
export const H = 568;
export const GROUND_Y = 420;

// ---------- color helpers ----------
function hexToRgb(hex) {
  const h = hex.replace('#', '');
  return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
}
export function rgbToHex(r, g, b) {
  const c = (v) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0');
  return '#' + c(r) + c(g) + c(b);
}
export function lerpColor(a, b, t) {
  const A = hexToRgb(a), B = hexToRgb(b);
  return rgbToHex(A[0] + (B[0] - A[0]) * t, A[1] + (B[1] - A[1]) * t, A[2] + (B[2] - A[2]) * t);
}
export function shade(hex, amount) {
  const A = hexToRgb(hex);
  if (amount >= 0) return rgbToHex(A[0] + (255 - A[0]) * amount, A[1] + (255 - A[1]) * amount, A[2] + (255 - A[2]) * amount);
  return rgbToHex(A[0] * (1 + amount), A[1] * (1 + amount), A[2] * (1 + amount));
}

// ---------- palettes by time of day ----------
const PALETTES = {
  sunset: {
    sky: ['#2a1a40', '#46234c', '#6d2f50', '#a33e4b', '#d46046', '#f18d4a', '#ffc36b'],
    sun: '#ffe9a8', sunGlow: '#ffb85c', cloud: '#7c3a55', cloudLit: '#e07a5f',
    far: '#8a4a52', mid: '#67323f', near: '#43222f',
    haze: '#e08a5a', lit: '#ffbd72',
    ground: '#6b3a33', groundLight: '#8f5138', groundDark: '#43242a',
    wood: '#5e3430', woodLight: '#8a4a35', woodDark: '#38202a',
    glow: '#ffb347',
  },
  dusk: {
    sky: ['#141a34', '#252144', '#402a4f', '#633a55', '#8f4a55', '#b96253', '#d98a5f'],
    sun: '#ffd9a0', sunGlow: '#e0895c', cloud: '#4d3150', cloudLit: '#a85c63',
    far: '#5c3a50', mid: '#442b40', near: '#2c1d31',
    haze: '#a8605f', lit: '#e09265',
    ground: '#51302f', groundLight: '#714132', groundDark: '#2f1d27',
    wood: '#4c2b2e', woodLight: '#744034', woodDark: '#2b1922',
    glow: '#ffc05a',
  },
  night: {
    sky: ['#070d20', '#0d1530', '#141f40', '#1d2b4d', '#2b3b58', '#3d4c63', '#58657a'],
    sun: '#dfe8ff', sunGlow: '#8496c4', cloud: '#232d49', cloudLit: '#52628a',
    far: '#2a3249', mid: '#1e2438', near: '#131927',
    haze: '#6a7899', lit: '#9fb0d4',
    ground: '#2a2431', groundLight: '#3d3039', groundDark: '#171520',
    wood: '#2e2430', woodLight: '#4a3537', woodDark: '#19131e',
    glow: '#ffcd6b',
  },
};

function mixPalette(a, b, t) {
  const out = {};
  for (const key of Object.keys(a)) {
    if (Array.isArray(a[key])) out[key] = a[key].map((c, i) => lerpColor(c, b[key][i], t));
    else out[key] = lerpColor(a[key], b[key], t);
  }
  return out;
}

/** dayT 0 = golden sunset, 0.5 = dusk, 1 = deep night */
export function paletteFor(dayT) {
  if (dayT <= 0.5) return mixPalette(PALETTES.sunset, PALETTES.dusk, dayT * 2);
  return mixPalette(PALETTES.dusk, PALETTES.night, (dayT - 0.5) * 2);
}

// ---------- deterministic randomness ----------
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rnd = mulberry32(1897);
const STARS = Array.from({ length: 46 }, () => ({
  x: Math.floor(rnd() * W),
  y: 40 + Math.floor(rnd() * 190),
  s: rnd() > 0.8 ? 2 : 1,
  phase: rnd() * Math.PI * 2,
  speed: 0.5 + rnd() * 1.5,
}));

const CLOUDS = [
  { x: 20, y: 88, w: 92, h: 12, drift: 2.2 },
  { x: 200, y: 132, w: 70, h: 10, drift: 3.1 },
  { x: 110, y: 58, w: 54, h: 8, drift: 1.5 },
  { x: 250, y: 70, w: 60, h: 9, drift: 2.6 },
];

const DUST = Array.from({ length: 30 }, () => ({
  x: rnd() * W, y: 220 + rnd() * 330, vx: 2 + rnd() * 6, vy: -1 + rnd() * 2,
  s: rnd() > 0.7 ? 2 : 1, phase: rnd() * 10,
}));

// ---------- primitives ----------
function rect(ctx, x, y, w, h, color) {
  ctx.fillStyle = color;
  ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
}

// Dithered horizontal bands -> soft pixel gradient.
function drawSky(ctx, pal, time) {
  const top = 46, bottom = 330;
  const colors = pal.sky;
  const bandH = (bottom - top) / (colors.length - 1);
  for (let i = 0; i < colors.length; i++) {
    const y = Math.round(top + i * bandH);
    const h = Math.ceil(bandH) + 1;
    rect(ctx, 0, y, W, h, colors[i]);
  }
  // checker dither between bands, 2px grid
  for (let i = 0; i < colors.length - 1; i++) {
    const y0 = Math.round(top + i * bandH) + Math.ceil(bandH) - 6;
    for (let x = 0; x < W; x += 2) {
      const row = (x / 2 + i) % 2;
      rect(ctx, x, y0 + (row ? 0 : 2), 2, 2, colors[i + 1]);
    }
  }

  // stars
  const starAlpha = Math.max(0, (pal === PALETTES.night ? 1 : 0));
  // derive alpha from sky darkness instead of identity
  const brightness = hexToRgb(pal.sky[0]);
  const dark = 1 - (brightness[0] + brightness[1] + brightness[2]) / 300;
  const sa = Math.max(0, Math.min(1, (dark - 0.55) * 3));
  if (sa > 0.02) {
    for (const s of STARS) {
      const tw = 0.55 + 0.45 * Math.sin(time * s.speed + s.phase);
      ctx.globalAlpha = sa * tw;
      rect(ctx, s.x, s.y, s.s, s.s, '#fdf3cf');
    }
    ctx.globalAlpha = 1;
  }

  // sun / moon path
  const sunX = 246;
  const sunY = 132 + Math.pow(dayProgressFromPal(pal), 1.4) * 150;
  drawSun(ctx, sunX, sunY, pal, time);

  // clouds
  for (const c of CLOUDS) {
    const cx = ((c.x + time * c.drift) % (W + c.w + 40)) - c.w - 20;
    drawCloud(ctx, Math.round(cx), c.y, c.w, c.h, pal, time, c);
  }

  // vultures (day) or bats (night) far off
  const vAlpha = 0.35 + 0.4 * (1 - sa);
  for (let i = 0; i < 3; i++) {
    const bx = 40 + i * 78 + Math.sin(time * 0.23 + i * 2.1) * 24;
    const by = 78 + i * 15 + Math.sin(time * 0.55 + i) * 5;
    drawVulture(ctx, bx, by, time * 2.4 + i, `rgba(40,20,34,${vAlpha})`);
  }
}

function dayProgressFromPal(pal) {
  // recover rough progress from sky top brightness: night is darkest
  const c = hexToRgb(pal.sky[0]);
  return 1 - Math.min(1, (c[0] + c[1] + c[2]) / 190);
}

function drawSun(ctx, x, y, pal, time) {
  const R = 30;
  // halo rings
  for (let ring = 4; ring >= 1; ring--) {
    ctx.globalAlpha = 0.055 * ring * 0.8;
    const r = R + ring * 9;
    for (let dy = -r; dy <= r; dy += 2) {
      const half = Math.floor(Math.sqrt(Math.max(0, r * r - dy * dy)));
      ctx.fillStyle = pal.sunGlow;
      ctx.fillRect(Math.round(x - half), Math.round(y + dy), half * 2, 2);
    }
  }
  ctx.globalAlpha = 1;
  // pixel circle body
  for (let dy = -R; dy < R; dy += 2) {
    const half = Math.floor(Math.sqrt(Math.max(0, R * R - dy * dy)));
    rect(ctx, x - half, y + dy, half * 2, 2, pal.sun);
  }
  // subtle banding on the sun
  ctx.globalAlpha = 0.16;
  for (let i = -1; i <= 1; i++) {
    const yy = y + i * 9;
    const half = Math.floor(Math.sqrt(Math.max(0, R * R - (i * 9) ** 2)));
    rect(ctx, x - half, yy, half * 2, 2, '#d98a5c');
  }
  ctx.globalAlpha = 1;
}

function drawCloud(ctx, x, y, w, h, pal, time, c) {
  const blocks = [
    [0, h * 0.5, w, h * 0.5],
    [w * 0.15, h * 0.25, w * 0.5, h * 0.5],
    [w * 0.4, 0, w * 0.38, h * 0.6],
    [w * 0.7, h * 0.3, w * 0.25, h * 0.4],
  ];
  // shadow layer
  for (const b of blocks) rect(ctx, x + b[0], y + b[1] + 2, b[2], b[3], pal.cloud);
  // lit top
  for (const b of blocks) rect(ctx, x + b[0], y + b[1], b[2], Math.max(2, b[3] * 0.45), pal.cloudLit);
  // highlights
  ctx.globalAlpha = 0.4;
  for (const b of blocks) rect(ctx, x + b[0], y + b[1], Math.max(2, b[2] * 0.7), 2, shade(pal.cloudLit, 0.3));
  ctx.globalAlpha = 1;
}

function drawVulture(ctx, x, y, flap, color) {
  const up = Math.sin(flap) > 0;
  ctx.fillStyle = color;
  const xs = Math.round(x), ys = Math.round(y);
  ctx.fillRect(xs - 6, ys + (up ? -1 : 1), 4, 1);
  ctx.fillRect(xs - 2, ys, 4, 1);
  ctx.fillRect(xs + 2, ys + (up ? -1 : 1), 4, 1);
  if (up) {
    ctx.fillRect(xs - 7, ys - 2, 2, 2);
    ctx.fillRect(xs + 5, ys - 2, 2, 2);
  }
}

// ---------- landscape ----------
function mesa(ctx, x, baseY, w, h, color, rim, seed) {
  const r = mulberry32(seed);
  // plateau silhouette
  const steps = Math.floor(w / 8);
  for (let i = 0; i < steps; i++) {
    const sx = x + i * 8;
    const edge = Math.min(i, steps - 1 - i);
    const jitter = Math.floor(r() * 14);
    const top = baseY - h + Math.min(18, edge * 9) + jitter;
    rect(ctx, sx, top, 8, baseY - top, color);
    if (edge > 1) rect(ctx, sx, top, 8, 2, rim);
  }
  // strata
  ctx.globalAlpha = 0.14;
  for (let i = 0; i < 3; i++) {
    rect(ctx, x + 10, baseY - h * 0.4 + i * 9, w - 20, 2, '#1b0f18');
  }
  ctx.globalAlpha = 1;
}

function drawMesas(ctx, pal) {
  mesa(ctx, -20, 348, 130, 96, pal.far, shade(pal.far, 0.16), 11);
  mesa(ctx, 88, 352, 120, 70, pal.far, shade(pal.far, 0.14), 22);
  mesa(ctx, 210, 350, 140, 108, pal.far, shade(pal.far, 0.18), 33);
  mesa(ctx, 30, 366, 90, 58, pal.mid, shade(pal.mid, 0.14), 44);
  mesa(ctx, 244, 368, 100, 62, pal.mid, shade(pal.mid, 0.14), 55);
  // haze line at the horizon
  ctx.globalAlpha = 0.25;
  rect(ctx, 0, 338, W, 10, pal.haze);
  ctx.globalAlpha = 1;
}

