  hidden: false,
};

// ---------------------------------------------------------------- setup
function prepareWave(w) {
  g.bossWave = w % 5 === 0;
  g.waveTarget = 5 + Math.floor(w * 0.9);
  g.maxActive = Math.min(4, 2 + Math.floor((w - 1) / 3));
