:root {
  --ink: #0c0710;
  --wood: #3a2026;
  --gold: #d9a24a;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: var(--ink);
  overflow: hidden;
  overscroll-behavior: none;
}

body {
  min-height: 100dvh;
  display: grid;
  place-items: center;
  font-family: "Courier New", monospace;
  color: #d8b98a;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
}

.backdrop {
  position: fixed;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 50% 0%, #3a1b2b 0%, #1a0d18 48%, #0a0610 100%),
    linear-gradient(180deg, #1a0d18, #0a0610);
  z-index: 0;
}

.backdrop .glow {
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(78vmin, 620px);
  height: min(78vmin, 620px);
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, rgba(217, 162, 74, 0.14) 0%, rgba(217, 162, 74, 0.05) 34%, transparent 68%);
  filter: blur(2px);
}

.backdrop .grain {
  position: absolute;
  inset: 0;
  opacity: 0.4;
  background-image:
    radial-gradient(rgba(255, 230, 180, 0.055) 1px, transparent 1px);
  background-size: 4px 4px;
  mask-image: radial-gradient(ellipse at center, black, transparent 80%);
  -webkit-mask-image: radial-gradient(ellipse at center, black, transparent 80%);
}

.stage {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  height: 100dvh;
  padding: env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left);
}

.cabinet {
  position: relative;
  line-height: 0;
  padding: 4px;
  background: linear-gradient(160deg, #5b3a2c, #25141c 55%, #0e0810);
  box-shadow:
    0 0 0 1px #8d6034,
    0 0 0 4px #1a0f16,
    0 18px 60px rgba(0, 0, 0, 0.75),
    0 0 44px rgba(217, 162, 74, 0.12);
  border-radius: 2px;
}

.cabinet::after {
  content: "";
  position: absolute;
  inset: 1px;
  pointer-events: none;
  box-shadow: inset 0 0 18px rgba(0, 0, 0, 0.5);
}

canvas {
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  touch-action: none;
  cursor: crosshair;
  background: #120a12;
}

.desk-hint {
  margin: 0;
  font-size: 10px;
  letter-spacing: 0.18em;
  color: rgba(216, 185, 138, 0.4);
  text-align: center;
  user-select: none;
  transition: opacity 0.4s;
}

@media (pointer: coarse) {
  .desk-hint { display: none; }
}

@media (max-height: 700px) {
  .stage { gap: 4px; }
  .cabinet { padding: 3px; }
}

@media (prefers-reduced-motion: reduce) {
  .backdrop .glow { filter: none; }
}

