432: function drawTinySign(ctx, str, cx, y, scale, color) {
433:   // a tiny block font shared with the saloon signs, 3x5
434:   const F = {
435:     A: ['010','101','111','101','101'], B: ['110','101','110','101','110'],
436:     C: ['011','100','100','100','011'], D: ['110','101','101','101','110'],
437:     E: ['111','100','110','100','111'], F: ['111','100','110','100','100'],
438:     G: ['011','100','101','101','011'], H: ['101','101','111','101','101'],
439:     I: ['111','010','010','010','111'], J: ['001','001','001','101','010'],
440:     K: ['101','101','110','101','101'], L: ['100','100','100','100','111'],
441:     M: ['101','111','111','101','101'], N: ['101','111','111','111','101'],
442:     O: ['010','101','101','101','010'], P: ['110','101','110','100','100'],
443:     Q: ['010','101','101','110','011'], R: ['110','101','110','101','101'],
444:     S: ['011','100','010','001','110'], T: ['111','010','010','010','010'],
445:     U: ['101','101','101','101','011'], V: ['101','101','101','101','010'],
446:     W: ['101','101','111','111','101'], X: ['101','101','010','101','101'],
447:     Y: ['101','101','010','010','010'], Z: ['111','001','010','100','111'],
448:     ' ': ['000','000','000','000','000'],
449:   };
450:   const s = str.toUpperCase();
451:   const cw = 3 * scale + scale;
452:   let x = Math.round(cx - (s.length * cw - scale) / 2);
453:   ctx.fillStyle = color;
454:   for (const ch of s) {
455:     const g = F[ch] || F[' '];
456:     for (let gy = 0; gy < 5; gy++) {
457:       for (let gx = 0; gx < 3; gx++) {
458:         if (g[gy][gx] === '1') ctx.fillRect(x + gx * scale, y + gy * scale, scale, scale);
459:       }
460:     }
461:     x += cw;
462:   }
463: }
