628: export function drawGround(ctx, pal, time, dayT) {
629:   // base street
630:   rect(ctx, 0, GROUND_Y - 4, W, H - GROUND_Y + 4, pal.ground);
631:   // perspective path
632:   const pathTop = GROUND_Y - 2, pathBot = H;
633:   for (let y = pathTop; y < pathBot; y += 4) {
634:     const t = (y - pathTop) / (pathBot - pathTop);
635:     const w = 80 + t * 240;
636:     const x = W / 2 - w / 2 + Math.sin(t * 3) * 8;
637:     rect(ctx, x, y, w, 4, pal.groundLight);
638:   }
639:   // horizontal dirt bands
640:   ctx.globalAlpha = 0.12;
641:   for (let i = 0; i < 6; i++) {
642:     const y = GROUND_Y + 12 + i * 26;
643:     rect(ctx, 0, y, W, 2, '#1c1016');
644:   }
645:   ctx.globalAlpha = 1;
646: 
647:   // wheel ruts
648:   ctx.globalAlpha = 0.25;
649:   for (const off of [-34, 12]) {
650:     for (let y = GROUND_Y + 6; y < H; y += 6) {
651:       const t = (y - GROUND_Y) / (H - GROUND_Y);
652:       const x = W / 2 + off * (0.5 + t * 1.4) + Math.sin(t * 4) * 4;
653:       rect(ctx, x, y, 2 + t * 4, 4, '#2f1b21');
654:     }
655:   }
656:   ctx.globalAlpha = 1;
657: 
658:   // pebbles & grass
659:   const r = mulberry32(77);
660:   for (let i = 0; i < 90; i++) {
661:     const x = r() * W;
662:     const y = GROUND_Y + r() * (H - GROUND_Y);
663:     const big = r() > 0.9;
664:     rect(ctx, x, y, big ? 2 : 1, big ? 2 : 1, r() > 0.5 ? pal.groundDark : shade(pal.groundLight, 0.12));
665:   }
666:   // tufts
667:   for (let i = 0; i < 12; i++) {
668:     const x = r() * W, y = GROUND_Y + 30 + r() * 110;
669:     const c = '#7d6a3a';
670:     ctx.globalAlpha = 0.55;
671:     rect(ctx, x, y, 1, 4, c);
672:     rect(ctx, x + 2, y + 1, 1, 3, c);
673:     rect(ctx, x - 2, y + 2, 1, 2, c);
674:     ctx.globalAlpha = 1;
675:   }
676: 
677:   // long shadows from buildings
678:   const dark = 'rgba(25,12,20,0.25)';
679:   rect(ctx, 0, GROUND_Y, 70, 16, dark);
680:   rect(ctx, 220, GROUND_Y, 100, 14, dark);
