686:     rect(ctx, 60, GROUND_Y + 4, 92, 44, '#c5813a');
687:     rect(ctx, 190, GROUND_Y + 4, 80, 40, '#c5813a');
688:     ctx.globalAlpha = 1;
689:   }
690: }
